:root {
  --bg: #ffffff;
  --bg-soft: #f7f7ff;
  --bg-alt: #f2f4ff;
  --text: #111827;
  --muted: #667085;
  --primary: #5b3df5;
  --primary-2: #7c4dff;
  --border: #e6e8f0;
  --success: #157347;
  --shadow: 0 10px 30px rgba(76, 68, 182, 0.12);
  --radius: 14px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: Inter, "Plus Jakarta Sans", system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(1160px, calc(100% - 2.5rem)); margin: 0 auto; }

.site-header {
  position: sticky; top: 0; z-index: 80;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
}
.nav-wrap { display: flex; align-items: center; justify-content: space-between; padding: 0.85rem 0; }
.brand { display: flex; align-items: center; gap: .55rem; font-weight: 800; font-size: 1.08rem; }
.brand-mark {
  width: 34px; height: 34px; border-radius: 10px;
  background: linear-gradient(135deg, var(--primary), #9a64ff);
  display: grid; place-items: center; color: #fff; font-weight: 800;
}
.nav-links { display: flex; gap: 1rem; align-items: center; }
.nav-links a { color: #3b3f55; font-weight: 600; padding: .45rem .7rem; border-radius: 10px; }
.nav-links a:hover { background: #f2f3ff; color: var(--primary); }
.nav-ctas { display: flex; gap: .65rem; align-items: center; }

.btn {
  border: 0; border-radius: 12px; padding: .74rem 1rem; font-weight: 700;
  display: inline-flex; align-items: center; justify-content: center; gap: .45rem;
  cursor: pointer; transition: transform .18s ease, box-shadow .2s ease, background .2s ease;
}
.btn:hover { transform: translateY(-1px); }
.btn-primary {
  color: #fff;
  background: linear-gradient(135deg, var(--primary), var(--primary-2));
  box-shadow: var(--shadow);
}
.btn-primary:hover { box-shadow: 0 14px 35px rgba(91, 61, 245, .24); }
.btn-light { background: #eef0ff; color: var(--primary); }
.btn-outline { border: 1px solid var(--border); background: #fff; }
.badge { background: #ece8ff; color: #5134e0; padding: .2rem .55rem; border-radius: 999px; font-weight: 700; font-size: .77rem; }

.hero {
  padding: 5.2rem 0 4.4rem;
  background:
    radial-gradient(circle at 8% 10%, rgba(124,77,255,.14), transparent 45%),
    radial-gradient(circle at 90% 28%, rgba(91,61,245,.14), transparent 45%),
    #fff;
}
.hero-grid { display: grid; grid-template-columns: 1.15fr .85fr; gap: 2rem; align-items: center; }
.hero h1 { font-size: clamp(2rem, 4vw, 3.4rem); line-height: 1.12; margin: 0 0 1rem; }
.hero p { color: var(--muted); font-size: 1.08rem; margin-bottom: 1.3rem; }
.mockup {
  border: 1px solid var(--border); border-radius: 18px; padding: 1rem;
  background: #fff; box-shadow: var(--shadow);
}
.mockup-top { display: flex; gap: .4rem; margin-bottom: .8rem; }
.dot { width: 10px; height: 10px; border-radius: 50%; background: #ddd; }
.screen {
  border-radius: 12px; min-height: 220px;
  background: linear-gradient(145deg, #f0edff, #fbfaff 56%, #ebe9ff);
  display: grid; place-items: center; color: #4f46e5; font-weight: 700;
}

section { padding: 4rem 0; }
.section-soft { background: var(--bg-soft); }
.section-alt { background: var(--bg-alt); }
.section-title { margin: 0 0 .65rem; font-size: clamp(1.55rem, 2.7vw, 2.2rem); line-height: 1.2; }
.section-sub { margin: 0 0 1.6rem; color: var(--muted); max-width: 740px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }
.card {
  background: #fff; border: 1px solid var(--border); border-radius: var(--radius);
  padding: 1rem; box-shadow: 0 4px 15px rgba(28, 25, 55, .04);
}
.card h3 { margin: .3rem 0 .45rem; font-size: 1.03rem; }
.card p { margin: 0; color: var(--muted); }
.icon-pill {
  width: 34px; height: 34px; border-radius: 10px;
  background: #eeebff; color: #5b3df5; display: grid; place-items: center; font-weight: 800;
}

.logo-row { display: grid; grid-template-columns: repeat(6, 1fr); gap: .8rem; }
.logo-chip { border: 1px solid var(--border); border-radius: 12px; padding: .85rem; text-align: center; color: #5e6480; font-weight: 700; background: #fff; }

.footer { padding: 2rem 0 3rem; border-top: 1px solid var(--border); color: #656b86; font-size: .95rem; }

.pricing-wrap { padding-top: 2.2rem; }
.billing-toggle {
  display: inline-flex; border: 1px solid var(--border); border-radius: 999px; padding: .3rem; gap: .4rem; background: #fff;
}
.billing-toggle button { border: 0; border-radius: 999px; padding: .4rem .9rem; background: transparent; font-weight: 700; cursor: pointer; }
.billing-toggle button.active { background: #ece8ff; color: #4a31d2; }

.team-size { margin: 1.2rem 0 1.6rem; max-width: 530px; }
.team-size label { display: flex; justify-content: space-between; font-weight: 700; margin-bottom: .55rem; }
input[type="range"] { width: 100%; accent-color: var(--primary); }

.plan-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }
.plan-price { font-size: 1.85rem; font-weight: 800; margin: .6rem 0 .2rem; }
.small { font-size: .9rem; color: var(--muted); }
ul.clean { list-style: none; margin: .8rem 0 0; padding: 0; }
ul.clean li { padding: .32rem 0; color: #313750; }
.expand-area { display: none; margin-top: .8rem; border-top: 1px dashed var(--border); padding-top: .75rem; }
.expand-area.open { display: block; }

.comparison { margin-top: 2rem; overflow-x: auto; }
table { width: 100%; border-collapse: collapse; min-width: 760px; background: #fff; border: 1px solid var(--border); border-radius: 12px; overflow: hidden; }
th, td { padding: .78rem; border-bottom: 1px solid var(--border); text-align: left; }
th { background: #f7f8ff; font-size: .9rem; }

.faq-item { border: 1px solid var(--border); border-radius: 12px; margin-bottom: .7rem; background: #fff; }
.faq-q { width: 100%; text-align: left; border: 0; background: transparent; padding: .9rem 1rem; font-weight: 700; cursor: pointer; }
.faq-a { display: none; padding: 0 1rem 1rem; color: var(--muted); }
.faq-item.open .faq-a { display: block; }

.auth-wrap { min-height: calc(100vh - 72px); display: grid; place-items: center; padding: 2rem 0; background: linear-gradient(180deg, #f8f8ff, #fff); }
.auth-card { width: min(980px, calc(100% - 2rem)); display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
.auth-form { background: #fff; border: 1px solid var(--border); border-radius: 16px; padding: 1.3rem; box-shadow: var(--shadow); }
.auth-side { background: #f6f4ff; border: 1px solid #e5e1ff; border-radius: 16px; padding: 1.3rem; }
.social-list { display: grid; gap: .6rem; margin: 1rem 0; }
.social-btn { border: 1px solid var(--border); background: #fff; border-radius: 10px; padding: .65rem .8rem; text-align: left; font-weight: 700; }
.input { width: 100%; border: 1px solid var(--border); border-radius: 10px; padding: .7rem .8rem; font-size: 1rem; }

.cookie-banner {
  position: fixed; left: 1rem; right: 1rem; bottom: 1rem; z-index: 95;
  background: #171a2b; color: #fff; border-radius: 14px; padding: 1rem;
  display: none;
}
.cookie-banner.show { display: block; }
.cookie-actions { display: flex; gap: .55rem; flex-wrap: wrap; margin-top: .7rem; }
.cookie-actions .btn-outline { background: transparent; color: #fff; border-color: rgba(255,255,255,.28); }
.modal-backdrop {
  position: fixed; inset: 0; background: rgba(12,12,30,.46); z-index: 98;
  display: none; align-items: center; justify-content: center;
}
.modal-backdrop.show { display: flex; }
.modal {
  width: min(560px, calc(100% - 2rem)); background: #fff; border-radius: 16px;
  padding: 1.2rem; border: 1px solid var(--border);
}
.pref-row { display: flex; justify-content: space-between; align-items: center; padding: .5rem 0; border-bottom: 1px solid #f1f2fa; }
.switch { position: relative; width: 44px; height: 24px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; inset: 0; background: #d7d9ea; border-radius: 999px; cursor: pointer; }
.slider:before { content: ""; width: 18px; height: 18px; position: absolute; left: 3px; top: 3px; border-radius: 50%; background: #fff; transition: .2s; }
.switch input:checked + .slider { background: var(--primary); }
.switch input:checked + .slider:before { transform: translateX(20px); }

@media (max-width: 1000px) {
  .hero-grid, .auth-card { grid-template-columns: 1fr; }
  .plan-grid { grid-template-columns: repeat(2, 1fr); }
  .logo-row { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 720px) {
  .nav-links { display: none; }
  .grid-3, .grid-2, .plan-grid { grid-template-columns: 1fr; }
}
